#!/usr/bin/env bash
# Halo CE Coop Evolved dedicated server on the dev host - Wine in a container.
# haloceded.exe is SAPP 10.3.2's build (sapp.dll + mimic_server + coop_evolved_server
# Lua). --net=host: Halo CE answers on UDP 2302 and LAN discovery is a broadcast.
# Config: data/load.txt (generated by `mercury serve`, then renamed/rcon set),
# data/sapp/init.txt. Maps: game/maps/*_coop_evolved.map + CE bitmaps/sounds/loc/ui.
set -euo pipefail
GAME_DIR="${GAME_DIR:-$HOME/haloce-server}"
IMAGE="${IMAGE:-retro-wine:bookworm}"
NAME="${NAME:-hcesrv}"
docker rm -f "$NAME" >/dev/null 2>&1 || true
exec docker run --rm --init --name "$NAME" --net=host \
    -v "$GAME_DIR:/hce" -v haloce-wineprefix:/wp \
    -e WINEDEBUG=-all -e WINEPREFIX=/wp \
    "$IMAGE" \
    bash -c 'cd /hce/game && (wineboot -i >/dev/null 2>&1 || true) && exec sleep infinity | wine haloceded.exe -path "Z:\\hce\\data" -exec "Z:\\hce\\data\\load.txt" -port 2302'
